package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.CompoundIndex;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("tracked_flights") @CompoundIndex(name="tracked_flight_user_unique",def="{'userId':1,'flightId':1}",unique=true) public class TrackedFlight{@Id private String id;@Indexed private String userId;@Indexed private String flightId;private Instant trackedAt=Instant.now();public String getId(){return id;}public String getUserId(){return userId;}public void setUserId(String x){userId=x;}public String getFlightId(){return flightId;}public void setFlightId(String x){flightId=x;}public Instant getTrackedAt(){return trackedAt;}}
